Q: How to create double range slider using native html input range and Vue.js? A: <p>I wanted to make a minimum and maximum range slider, and I think I came up with a pretty elegant solution, using only HTML and plain JavaScript.</p>
<p>This creates a double range slider so you can select minimum and maximum.
It uses 2 range sliders right next to each other. The minimum slider is a range slider going right to left.
When you &quot;mousedown&quot; on one slider it changes the width so it goes all the way up to the value of the other slider.
The value reported by the minimum slider is calculated with a formula, because the max value is on the left and the min value is on the right.
The sliders have a slight gap between - if you don't like this it can be removed with negative margins.</p>
<p>The script searches for container elements (like <code>&lt;td&gt;</code> or <code>&lt;div&gt;</code>) with class 'double_range'.
Inside the container element, the double range slider needs these elements.</p>
<ul>
<li><code>&lt;input type='range' class='double_range_min'&gt;</code> (if min value is not set it defaults to 0, and if step value is not set it defaults to 1)</li>
<li><code>&lt;input type='range' class='double_range_max' max='x'&gt;</code> (max value must be set)</li>
<li>element (like <code>&lt;span&gt;</code> or <code>&lt;div&gt;</code>) with class 'double_range_min_limit' to show minimum limit</li>
<li>element (like <code>&lt;span&gt;</code> or <code>&lt;div&gt;</code>) with class 'double_range_max_limit' to show maximum limit</li>
<li>element (like <code>&lt;span&gt;</code> or <code>&lt;div&gt;</code>) with class 'double_range_min_output' to show current minimum value</li>
<li>element (like <code>&lt;span&gt;</code> or <code>&lt;div&gt;</code>) with class 'double_range_max_output' to show current maximum value</li>
</ul>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="false" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const DOUBLE_RANGE_WIDTH = 1000;

function min_display_value(min) {
/*This function returns the display value of the minimum range (which goes right-to-left).*/
  return min.max - min.value + parseInt(min.min);
}

function update_double_range_outputs(double_range) {
/*This function displays the double range values.*/
  let min = double_range.querySelector(".double_range_min");
  let max = double_range.querySelector(".double_range_max");
  double_range.querySelector(".double_range_min_output").textContent = min_display_value(min);
  double_range.querySelector(".double_range_max_output").textContent = max.value;
}

function update_double_range_width(double_range) {
/*This function updates the widths of the minimum and maximum sliders.*/
  let min = double_range.querySelector(".double_range_min");
  let max = double_range.querySelector(".double_range_max");
  /*SIZE is how many pixels for each number on slider*/
  const SIZE = DOUBLE_RANGE_WIDTH / (max.max - min.min);
  /*set width of minimum slider - if either end is 0 make it 16 to give it room to display*/
  if (min.min == min.max) {
    min.style.width = "16px";
  } else if (max.min == max.max) {
    min.style.width = (DOUBLE_RANGE_WIDTH - 16) + "px";
  } else {
    min.style.width = Math.floor((min.max - min.min) * SIZE) + "px";
  }
  /*set width of maximum slider*/
  max.style.width = (DOUBLE_RANGE_WIDTH - parseInt(min.style.width)) + "px";
}

let double_ranges = document.querySelectorAll(".double_range");
for (let i = 0; i &lt; double_ranges.length; i++) {
  let min = double_ranges[i].querySelector(".double_range_min");
  let max = double_ranges[i].querySelector(".double_range_max");
  if (min.min == "") {
    min.min = "0";
  }
  if (min.step == "") {
    min.step = "1";
  }
  min.style.direction = "rtl";
  min.style.marginRight = 0;
  min.style.marginLeft = 0;
  min.parentElement.style.display = "flex";
  double_ranges[i].querySelector(".double_range_min_limit").textContent = min.min;
  double_ranges[i].querySelector(".double_range_max_limit").textContent = max.max;
  min.max = max.max;
  max.min = min.max;
  max.step = min.step;
  min.value = min.max;
  max.value = max.max;
  update_double_range_outputs(double_ranges[i]);
  update_double_range_width(double_ranges[i]);

  min.addEventListener("input", function(e) {
    update_double_range_outputs(double_ranges[i]);
  });

  max.addEventListener("input", function(e) {
    update_double_range_outputs(double_ranges[i]);
  });

  min.addEventListener("mousedown", function(e) {
    /*keep previous min.max to work out new min.value*/
    let previous_max = min.max;
    /*make minimum slider end right before maximum value*/
    min.max = max.value;
    max.min = min.max;
    /*work out new min.value*/
    min.value = min.max - previous_max + parseInt(min.value);
    update_double_range_width(double_ranges[i]);
  });

  max.addEventListener("mousedown", function(e) {
    /*make maximum slider start right after minimum value*/
    max.min = min_display_value(min);
    min.max = max.min;
    min.value = min.min;
    update_double_range_width(double_ranges[i]);
  });
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div class='double_range'&gt;
    &lt;div&gt;
        &lt;span class='double_range_min_limit'&gt;&lt;/span&gt;
        &lt;input type='range' class='double_range_min' step='500'&gt;&lt;input type='range' class='double_range_max' max='10000'&gt;
        &lt;span class='double_range_max_limit'&gt;&lt;/span&gt;
    &lt;/div&gt;
    &lt;div&gt;min: &lt;span class='double_range_min_output'&gt;&lt;/span&gt;&lt;/div&gt;
    &lt;div&gt;max: &lt;span class='double_range_max_output'&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;</code></pre>
